SELECT fp2.FINPROD_ABBR||'('||fp2.FINPROD_MARKET_ID||')' AS inProdName, fp3.FINPROD_ABBR||'('||fp3.FINPROD_MARKET_ID||')' AS outprodName, TRD_PRODUCT_DEAL.FINPROD_TYPE2 AS trdType1, '' AS trdType2, fp1.FINPROD_ABBR AS assetName, fp1.FINPROD_MARKET_ID AS assetId, TO_CHAR(TRD_PRODUCT_DEAL.TRADE_DATE, 'yyyy-MM-dd') AS tradeDate , TO_CHAR(TRD_PRODUCT_DEAL.SETTLE_DATE, 'yyyy-MM-dd') AS settleDate, TRD_PRODUCT_DEAL.UNIT_CPRICE AS unitCprice, TRD_PRODUCT_DEAL.UNIT_FPRICE AS unitFprice, TRD_PRODUCT_DEAL.SHARE_AMT*100/10000 AS tradeAmt, TRD_PRODUCT_DEAL.FPRICE_AMT AS fpriceAmt, to_char(NVL(TRD_PRODUCT_DEAL.YIELD,0)*100) AS yield FROM TRD_PRODUCT_DEAL INNER JOIN TRD_PRODUCT_DEAL_ADD dadd ON dadd.TRADE_ID = TRD_PRODUCT_DEAL.TRADE_ID LEFT JOIN FIN_PRODUCT_ADD fpa ON fpa.PORTFOLIO_ID = dadd.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT fp3 ON fp3.FINPROD_ID = fpa.FINPROD_ID LEFT JOIN FIN_PRODUCT fp1 ON fp1.FINPROD_ID = TRD_PRODUCT_DEAL.FINPROD_ID LEFT JOIN FIN_PRODUCT fp2 ON fp2.FINPROD_MARKET_ID = TRD_PRODUCT_DEAL.COUNTER_ID WHERE TRD_PRODUCT_DEAL.FINPROD_TYPE2 ='F01'
AND TRD_PRODUCT_DEAL.TRADE_ID IN(
#{item}
)

